const esc = (v) => String(v ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

let diagnosis = {};
try { diagnosis = JSON.parse($json.diagnosis_json || '{}'); } catch (e) { diagnosis = { root_cause: '(diagnóstico ilegível)' }; }

const incidentId = esc($json.id);
const token = esc($('Webhook').item.json.query.token);
const canApprove = $json.can_approve === true;

const hidden = (action) => `
      <input type="hidden" name="incident" value="${incidentId}">
      <input type="hidden" name="token" value="${token}">
      <input type="hidden" name="action" value="${action}">`;

const decisionButtons = canApprove ? `
    <form method="POST" action="http://localhost:5678/webhook/heal-decide" style="display:inline;">${hidden('approve')}
      <button type="submit" style="background:#22c55e;color:white;padding:10px 20px;border:none;border-radius:6px;font-size:16px;">✅ Approve</button>
    </form>
    <form method="POST" action="http://localhost:5678/webhook/heal-decide" style="display:inline; margin-left:10px;">${hidden('reject')}
      <button type="submit" style="background:#ef4444;color:white;padding:10px 20px;border:none;border-radius:6px;font-size:16px;">❌ Reject</button>
    </form>` : `
    <p style="background:#fef3c7;padding:12px;border-radius:6px;">
      👀 Seu nível (<strong>${esc($json.permission_level)}</strong>) não permite aprovar um incidente de severidade
      <strong>${esc($json.severity)}</strong>. Você pode deixar uma sugestão para quem aprova.
    </p>`;

const html = `<!doctype html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="font-family: sans-serif; max-width: 600px; margin: 40px auto; padding: 20px;">
  <h1>🔍 Incident Review</h1>
  <p><em>Olá, ${esc($json.approver_name)} (${esc($json.permission_level)})</em></p>
  <p><strong>Workflow:</strong> ${esc($json.workflow_name)}</p>
  <p><strong>Node:</strong> ${esc($json.node_name)}</p>
  <p><strong>Severity:</strong> ${esc($json.severity)}</p>
  <p><strong>Error:</strong> ${esc($json.error_message)}</p>
  <hr>
  <p><strong>Root cause:</strong> ${esc(diagnosis.root_cause)}</p>
  <p><strong>Proposed fix:</strong> ${esc(diagnosis.proposed_fix || 'None identified')}</p>
  <p><strong>Risk:</strong> ${esc(diagnosis.risk)} | <strong>Confidence:</strong> ${esc(diagnosis.confidence)}</p>
  <div style="margin-top: 30px;">${decisionButtons}
  </div>
  <hr style="margin-top:40px">
  <form method="POST" action="http://localhost:5678/webhook/heal-decide">${hidden('suggest')}
    <p><strong>💬 Sugestão</strong> (não aprova nem consome o link)</p>
    <textarea name="suggestion" rows="4" maxlength="2000" style="width:100%;" required></textarea>
    <button type="submit" style="margin-top:8px;padding:8px 16px;">Enviar sugestão</button>
  </form>
</body></html>`;

return [{ json: { html } }];
